mapper.select:
SELECT u1.user_name AS senderName, u2.user_name AS recipientName, cr.resource_name AS topic,
FROM ask_questions aq LEFT JOIN `user` u1 ON u1.id = aq.sender LEFT JOIN `user` u2 ON u2.id = aq.recipient LEFT JOIN course_resource cr ON cr.id = aq.resource_id
AND (aq.sender = #{userId} OR aq.recipient = #{userId})
AND aq.content LIKE CONCAT('%', #{content}, '%')
AND aq.recipient = #{recipient}
ORDER BY aq.id DESC LIMIT #{page},#{pageSize}
